function draw(){
    ctx.clearRect(0,0,W,H);
    // background stars
    ctx.fillStyle = '#000';
    ctx.fillRect(0,0,W,H);
    // update and draw stars
    updateStars(dt);
    drawStars();
    // rocket
    ctx.fillStyle = 'red';
    ctx.fillRect(rocket.x, rocket.y, rocket.w, rocket.h);
